const fs = await import('node:fs').catch(() => null);
// Read the DSL file via shell? No - use tools only. Let's inspect the workspace.
const dsl = `workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}`;
const [inspect, parse, validate] = await Promise.allSettled([
  tools.structurizr.inspect({ dsl }),
  tools.structurizr.parse({ dsl }),
  tools.structurizr.validate({ dsl }),
]);
return {
  inspect: inspect.status === 'fulfilled' ? inspect.value : inspect.reason,
  parse: parse.status === 'fulfilled' ? parse.value : parse.reason,
  validate: validate.status === 'fulfilled' ? validate.value : validate.reason,
};

